const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  Table, TableRow, TableCell, WidthType, ShadingType, BorderStyle,
  PageBreak, LevelFormat, convertInchesToTwip
} = require("docx");

const FONT = "Calibri";

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 400, after: 200 },
    children: [new TextRun({ text, bold: true })],
  });
}
function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 300, after: 150 },
    children: [new TextRun({ text, bold: true })],
  });
}
function body(text, opts = {}) {
  return new Paragraph({
    spacing: { after: 160 },
    children: [new TextRun({ text, font: FONT, size: 22, ...opts })],
  });
}
function instruction(text) {
  return new Paragraph({
    spacing: { after: 200 },
    indent: { left: convertInchesToTwip(0.2) },
    children: [new TextRun({ text, italics: true, color: "555555", font: FONT, size: 20 })],
  });
}
function bullet(text) {
  return new Paragraph({
    numbering: { reference: "bullet-list", level: 0 },
    spacing: { after: 100 },
    children: [new TextRun({ text, font: FONT, size: 22 })],
  });
}
function numbered(text) {
  return new Paragraph({
    numbering: { reference: "num-list", level: 0 },
    spacing: { after: 100 },
    children: [new TextRun({ text, font: FONT, size: 22 })],
  });
}

function cell(text, opts = {}) {
  return new TableCell({
    width: { size: opts.width || 2000, type: WidthType.DXA },
    shading: opts.header ? { type: ShadingType.CLEAR, fill: "1F4E79" } : undefined,
    margins: { top: 100, bottom: 100, left: 100, right: 100 },
    children: [new Paragraph({
      children: [new TextRun({
        text, bold: !!opts.header, italics: !!opts.italics,
        color: opts.header ? "FFFFFF" : "000000", font: FONT, size: 20,
      })],
    })],
  });
}

const matrixWidths = [1700, 3000, 3000, 2700, 2600];
const matrixHeader = new TableRow({
  tableHeader: true,
  children: [
    cell("Kode & Nama\nMata Kuliah", { header: true, width: matrixWidths[0] }),
    cell("Capaian Pembelajaran\nMata Kuliah (CPMK)", { header: true, width: matrixWidths[1] }),
    cell("Uraian Pengalaman Kerja\nyang Relevan", { header: true, width: matrixWidths[2] }),
    cell("Bukti Pendukung\n(dokumen/lampiran)", { header: true, width: matrixWidths[3] }),
    cell("Refleksi /\nSelf-Assessment", { header: true, width: matrixWidths[4] }),
  ],
});
function matrixExampleRow() {
  return new TableRow({
    children: [
      cell("[Isi: cth. MJN201 – Manajemen SDM]", { width: matrixWidths[0], italics: true }),
      cell("[Isi capaian pembelajaran sesuai silabus kampus]", { width: matrixWidths[1], italics: true }),
      cell("[Ceritakan pengalaman kerja konkret yang menunjukkan kompetensi ini]", { width: matrixWidths[2], italics: true }),
      cell("[Sebutkan nomor lampiran: SK, surat tugas, sertifikat, dll]", { width: matrixWidths[3], italics: true }),
      cell("[Jelaskan apa yang Anda pelajari/kuasai dari pengalaman ini]", { width: matrixWidths[4], italics: true }),
    ],
  });
}
function matrixBlankRow() {
  return new TableRow({
    children: matrixWidths.map((w) => cell("", { width: w })),
  });
}

const evidenceWidths = [800, 4000, 2200, 2100, 1900];
const evidenceHeader = new TableRow({
  tableHeader: true,
  children: [
    cell("No.", { header: true, width: evidenceWidths[0] }),
    cell("Nama Dokumen Bukti", { header: true, width: evidenceWidths[1] }),
    cell("Penerbit / Sumber", { header: true, width: evidenceWidths[2] }),
    cell("Tahun", { header: true, width: evidenceWidths[3] }),
    cell("No. Lampiran", { header: true, width: evidenceWidths[4] }),
  ],
});
function evidenceBlankRow(no) {
  return new TableRow({
    children: [
      cell(String(no), { width: evidenceWidths[0] }),
      cell("", { width: evidenceWidths[1] }),
      cell("", { width: evidenceWidths[2] }),
      cell("", { width: evidenceWidths[3] }),
      cell("", { width: evidenceWidths[4] }),
    ],
  });
}

const bioWidths = [2800, 6200];
function bioRow(label, placeholder) {
  return new TableRow({
    children: [
      cell(label, { header: false, width: bioWidths[0] }),
      cell(placeholder, { width: bioWidths[1], italics: true }),
    ],
  });
}

const doc = new Document({
  numbering: {
    config: [
      {
        reference: "bullet-list",
        levels: [{ level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }],
      },
      {
        reference: "num-list",
        levels: [{ level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }],
      },
    ],
  },
  sections: [{
    properties: {
      page: {
        size: { width: 11906, height: 16838 }, // A4
        margin: { top: 1440, bottom: 1440, left: 1440, right: 1440 },
      },
    },
    children: [
      // COVER
      new Paragraph({ spacing: { before: 1600 }, alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "PORTOFOLIO", bold: true, size: 44, font: FONT })] }),
      new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 200 },
        children: [new TextRun({ text: "REKOGNISI PEMBELAJARAN LAMPAU (RPL) TIPE A", bold: true, size: 32, font: FONT })] }),
      new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 200 },
        children: [new TextRun({ text: "PROGRAM STUDI S1 MANAJEMEN", bold: true, size: 28, font: FONT })] }),
      new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 800 },
        children: [new TextRun({ text: "Jalur Pengakuan Pengalaman Kerja", italics: true, size: 24, font: FONT })] }),
      new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 100 },
        children: [new TextRun({ text: "Diajukan oleh:", size: 22, font: FONT })] }),
      new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 100 },
        children: [new TextRun({ text: "[Nama Lengkap Pemohon]", bold: true, size: 26, font: FONT })] }),
      new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 1200 },
        children: [new TextRun({ text: "[Nomor Identitas / NIK / No. Pendaftaran]", size: 22, font: FONT })] }),
      new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 2400 },
        children: [new TextRun({ text: "[Nama Perguruan Tinggi Tujuan]", bold: true, size: 24, font: FONT })] }),
      new Paragraph({ alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "[Tahun Pengajuan]", size: 24, font: FONT })] }),
      new Paragraph({ children: [new PageBreak()] }),

      // KATA PENGANTAR
      h1("KATA PENGANTAR"),
      instruction("Tuliskan ucapan syukur, tujuan penyusunan portofolio, dan ucapan terima kasih pihak terkait (atasan, keluarga, kampus). 1–2 paragraf singkat."),
      new Paragraph({ children: [new PageBreak()] }),

      // DAFTAR ISI
      h1("DAFTAR ISI"),
      instruction("Buat daftar isi otomatis di Word (References → Table of Contents) setelah seluruh dokumen selesai diisi, atau tulis manual sesuai nomor halaman akhir."),
      new Paragraph({ children: [new PageBreak()] }),

      // BAB I
      h1("BAB I — IDENTITAS DIRI"),
      body("Lengkapi tabel biodata berikut sesuai dokumen identitas resmi (KTP/Ijazah)."),
      new Table({
        width: { size: 9000, type: WidthType.DXA },
        rows: [
          bioRow("Nama Lengkap", "[Isi nama lengkap sesuai KTP]"),
          bioRow("Tempat, Tanggal Lahir", "[Isi]"),
          bioRow("NIK", "[Isi]"),
          bioRow("Alamat Domisili", "[Isi]"),
          bioRow("No. Telepon / WhatsApp", "[Isi]"),
          bioRow("Email", "[Isi]"),
          bioRow("Pekerjaan Saat Ini", "[Isi jabatan & instansi]"),
          bioRow("Lama Bekerja", "[Isi total tahun pengalaman kerja relevan]"),
        ],
      }),
      new Paragraph({ children: [new PageBreak()] }),

      // BAB II
      h1("BAB II — RIWAYAT PENDIDIKAN FORMAL"),
      instruction("Urutkan dari jenjang terakhir ke yang paling awal (SMA/SMK, dan pendidikan lain jika ada, misal D3)."),
      numbered("[Jenjang] — [Nama Sekolah/Institusi], Tahun lulus [____], Jurusan [____]"),
      numbered("[Tambahkan baris lain sesuai kebutuhan]"),
      new Paragraph({ children: [new PageBreak()] }),

      // BAB III
      h1("BAB III — RIWAYAT PENGALAMAN KERJA & ORGANISASI"),
      instruction("Susun kronologis (dari yang terbaru), sebutkan nama instansi, posisi/jabatan, periode, dan uraian singkat tanggung jawab utama. Fokuskan pada pengalaman yang relevan dengan bidang Manajemen (SDM, keuangan, operasional, pemasaran, kepemimpinan, dsb)."),
      h2("Pengalaman Kerja"),
      bullet("[Nama Instansi] — [Jabatan] ([Bulan/Tahun] – [Bulan/Tahun])"),
      instruction("   Uraikan 2–4 tanggung jawab/pencapaian utama pada posisi ini."),
      bullet("[Tambahkan pengalaman kerja lain]"),
      h2("Pengalaman Organisasi / Pelatihan (opsional)"),
      bullet("[Nama organisasi/pelatihan] — [Peran] ([Tahun])"),
      new Paragraph({ children: [new PageBreak()] }),

      // BAB IV
      h1("BAB IV — ASESMEN MANDIRI CAPAIAN PEMBELAJARAN"),
      instruction("Ini bagian inti portofolio RPL: petakan pengalaman kerja Anda ke mata kuliah/capaian pembelajaran program studi S1 Manajemen. Minta daftar mata kuliah & CPMK yang bisa diklaim dari bagian akademik kampus tujuan, lalu isi tabel di bawah ini untuk setiap mata kuliah. Salin baris tabel sesuai jumlah mata kuliah yang diajukan."),
      new Table({
        width: { size: 13000, type: WidthType.DXA },
        rows: [matrixHeader, matrixExampleRow(), matrixBlankRow(), matrixBlankRow(), matrixBlankRow()],
      }),
      new Paragraph({ children: [new PageBreak()] }),

      // BAB V
      h1("BAB V — DAFTAR BUKTI PENDUKUNG (EVIDENCE)"),
      instruction("Daftar semua dokumen bukti yang dilampirkan: surat keterangan kerja, SK jabatan, sertifikat pelatihan, penghargaan, hasil kerja/proyek, surat rekomendasi atasan, dll. Nomor lampiran harus konsisten dengan yang dirujuk pada tabel Bab IV."),
      new Table({
        width: { size: 11000, type: WidthType.DXA },
        rows: [evidenceHeader, evidenceBlankRow(1), evidenceBlankRow(2), evidenceBlankRow(3), evidenceBlankRow(4), evidenceBlankRow(5)],
      }),
      new Paragraph({ children: [new PageBreak()] }),

      // BAB VI
      h1("BAB VI — SURAT PERNYATAAN KEASLIAN DOKUMEN"),
      instruction("Contoh teks pernyataan — sesuaikan dengan format resmi kampus jika disediakan."),
      body("Saya yang bertanda tangan di bawah ini:"),
      body("Nama\t: [Isi nama lengkap]"),
      body("NIK\t: [Isi]"),
      body("menyatakan dengan sesungguhnya bahwa seluruh data, informasi, dan dokumen bukti yang dilampirkan dalam portofolio Rekognisi Pembelajaran Lampau (RPL) ini adalah benar dan dapat dipertanggungjawabkan. Apabila di kemudian hari ditemukan ketidaksesuaian, saya bersedia menerima konsekuensi sesuai ketentuan yang berlaku di [Nama Perguruan Tinggi]."),
      new Paragraph({ spacing: { before: 400 }, alignment: AlignmentType.RIGHT,
        children: [new TextRun({ text: "[Kota], [Tanggal/Bulan/Tahun]", font: FONT, size: 22 })] }),
      new Paragraph({ spacing: { before: 800 }, alignment: AlignmentType.RIGHT,
        children: [new TextRun({ text: "Materai 10.000", italics: true, font: FONT, size: 20 })] }),
      new Paragraph({ spacing: { before: 200 }, alignment: AlignmentType.RIGHT,
        children: [new TextRun({ text: "( [Nama Lengkap & Tanda Tangan] )", font: FONT, size: 22 })] }),
      new Paragraph({ children: [new PageBreak()] }),

      // LAMPIRAN
      h1("LAMPIRAN"),
      instruction("Susun salinan/scan dokumen bukti sesuai urutan nomor lampiran pada Bab V. Beri sekat/halaman pembatas untuk tiap lampiran agar mudah ditelusuri asesor."),
    ],
  }],
});

Packer.toBuffer(doc).then((buf) => {
  require("fs").writeFileSync(process.argv[2], buf);
  console.log("written:", process.argv[2]);
});

