const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  Table, TableRow, TableCell, WidthType, ShadingType, VerticalAlign,
  PageBreak, LevelFormat,
} = require("docx");

const FONT = "Calibri";

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 400, after: 200 },
    children: [new TextRun({ text, bold: true })],
  });
}
function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 260, after: 120 },
    children: [new TextRun({ text, bold: true })],
  });
}
function body(text, opts = {}) {
  return new Paragraph({
    spacing: { after: 160 },
    children: [new TextRun({ text, font: FONT, size: 22, ...opts })],
  });
}
function note(text) {
  return new Paragraph({
    spacing: { after: 200 },
    shading: { type: ShadingType.CLEAR, fill: "F2F2F2" },
    children: [new TextRun({ text, italics: true, color: "444444", font: FONT, size: 19 })],
  });
}
function bullet(text, opts = {}) {
  return new Paragraph({
    numbering: { reference: "bullet-list", level: opts.level || 0 },
    spacing: { after: 90 },
    children: [new TextRun({ text, font: FONT, size: 22, bold: !!opts.bold })],
  });
}

function cell(text, opts = {}) {
  return new TableCell({
    width: { size: opts.width || 2000, type: WidthType.DXA },
    columnSpan: opts.span,
    verticalAlign: VerticalAlign.CENTER,
    shading: opts.header
      ? { type: ShadingType.CLEAR, fill: "1F4E79" }
      : opts.sub
      ? { type: ShadingType.CLEAR, fill: "D9E2F3" }
      : undefined,
    margins: { top: 80, bottom: 80, left: 100, right: 100 },
    children: [new Paragraph({
      alignment: opts.center ? AlignmentType.CENTER : undefined,
      children: [new TextRun({
        text, bold: !!opts.header || !!opts.bold, italics: !!opts.italics,
        color: opts.header ? "FFFFFF" : "000000", font: FONT, size: opts.size || 19,
      })],
    })],
  });
}

// ---------- BAB VI: Asesmen Mandiri matrix ----------
