const assessmentRows = [
  ["Pengantar Bisnis", "2", "Membangun dan menjalankan operasional bisnis F&B multi-outlet dari nol; memahami siklus bisnis end-to-end (pengadaan-produksi-penjualan-pelaporan).", "Lampiran A"],
  ["Pengantar Manajemen", "3", "Merancang dan mengimplementasikan SOP Purchasing, Inventory Control, serta Finance & Accounting untuk unit usaha baru.", "Lampiran A"],
  ["Pengantar Akuntansi", "3", "Menyusun laporan laba rugi, rekonsiliasi pendapatan, dan pencatatan transaksi harian multi-outlet.", "Lampiran A, B, D"],
