const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  Table, TableRow, TableCell, WidthType, ShadingType, VerticalAlign,
  PageBreak, LevelFormat, BorderStyle,
} = require("docx");

const FONT = "Calibri";
const PRIMARY = "1F6FB2";      // accent blue
const PRIMARY_DARK = "0C447C"; // navy (headings, table headers)
const BG_LIGHT = "EAF2FB";     // light blue card bg
const BG_ZEBRA = "F5F8FC";     // subtle zebra stripe
const BG_GREEN = "E6F4EA";     // claimed / "Ya" badge bg
const TEXT_GREEN = "1E7B34";
const TEXT_MUTED = "6B6B6B";

const NO_BORDERS = {
  top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  left: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  right: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  insideHorizontal: { style: BorderStyle.SINGLE, size: 6, color: "FFFFFF" },
  insideVertical: { style: BorderStyle.SINGLE, size: 24, color: "FFFFFF" },
};

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 480, after: 220 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: PRIMARY, space: 6 } },
    children: [
      new TextRun({ text: "  ", shading: { type: ShadingType.CLEAR, fill: PRIMARY } }),
      new TextRun({ text: "  " + text, bold: true, color: PRIMARY_DARK, size: 30, font: FONT }),
    ],
  });
}
function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 260, after: 120 },
    children: [new TextRun({ text, bold: true, color: PRIMARY_DARK, size: 23, font: FONT })],
  });
}
function body(text, opts = {}) {
  return new Paragraph({
    spacing: { after: 160 },
    children: [new TextRun({ text, font: FONT, size: 22, color: "222222", ...opts })],
  });
}
function note(text) {
  return new Paragraph({
    spacing: { after: 200 },
    shading: { type: ShadingType.CLEAR, fill: BG_LIGHT },
    border: { left: { style: BorderStyle.SINGLE, size: 18, color: PRIMARY, space: 8 } },
    indent: { left: 60 },
    children: [new TextRun({ text, color: PRIMARY_DARK, font: FONT, size: 19 })],
  });
}
function bullet(text, opts = {}) {
  return new Paragraph({
    numbering: { reference: "bullet-list", level: opts.level || 0 },
    spacing: { after: 100 },
    children: [new TextRun({ text, font: FONT, size: 22, bold: !!opts.bold, color: "222222" })],
  });
}

function cell(text, opts = {}) {
  const fill = opts.header ? PRIMARY_DARK : opts.sub ? BG_LIGHT : opts.green ? BG_GREEN : opts.zebra ? BG_ZEBRA : undefined;
  const textColor = opts.header ? "FFFFFF" : opts.green ? TEXT_GREEN : opts.muted ? TEXT_MUTED : "1A1A1A";
  return new TableCell({
    width: { size: opts.width || 2000, type: WidthType.DXA },
    columnSpan: opts.span,
    verticalAlign: VerticalAlign.CENTER,
    shading: fill ? { type: ShadingType.CLEAR, fill } : undefined,
    margins: { top: 80, bottom: 80, left: 100, right: 100 },
    children: [new Paragraph({
      alignment: opts.center ? AlignmentType.CENTER : undefined,
      children: [new TextRun({
        text, bold: !!opts.header || !!opts.bold, italics: !!opts.italics,
        color: textColor, font: FONT, size: opts.size || 19,
      })],
    })],
  });
}

// small stat-card row (borderless table with shaded cells)
function statCardRow(items) {
  const total = 10800;
  const w = Math.floor(total / items.length);
  return new Table({
    width: { size: total, type: WidthType.DXA },
    borders: NO_BORDERS,
    rows: [new TableRow({
      children: items.map((it) => new TableCell({
        width: { size: w, type: WidthType.DXA },
        shading: { type: ShadingType.CLEAR, fill: BG_LIGHT },
        margins: { top: 180, bottom: 180, left: 160, right: 160 },
        children: [
          new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 40 },
            children: [new TextRun({ text: it.label, color: TEXT_MUTED, size: 17, font: FONT })] }),
          new Paragraph({ alignment: AlignmentType.CENTER,
            children: [new TextRun({ text: it.value, bold: true, color: PRIMARY_DARK, size: 30, font: FONT })] }),
        ],
      })),
    })],
  });
}

// 2-column impact-card grid (borderless table)
function impactCardGrid(cards) {
  const total = 10800;
  const w = Math.floor(total / 2);
  function card(c) {
    return new TableCell({
      width: { size: w, type: WidthType.DXA },
      shading: { type: ShadingType.CLEAR, fill: BG_LIGHT },
      margins: { top: 200, bottom: 200, left: 220, right: 220 },
      children: [
        new Paragraph({ spacing: { after: 70 },
          children: [new TextRun({ text: c.title, bold: true, color: PRIMARY_DARK, size: 21, font: FONT })] }),
        new Paragraph({
          children: [new TextRun({ text: c.desc, color: "222222", size: 19, font: FONT })] }),
      ],
    });
  }
  const rows = [];
  for (let i = 0; i < cards.length; i += 2) {
    rows.push(new TableRow({ children: [card(cards[i]), cards[i + 1] ? card(cards[i + 1]) : new TableCell({ width: { size: w, type: WidthType.DXA }, children: [new Paragraph({})] })] }));
  }
  return new Table({ width: { size: total, type: WidthType.DXA }, borders: NO_BORDERS, rows });
}

// project "card" made from two bordered/shaded paragraphs (title + body)
function projectCard(title, desc) {
  const frame = { top: { style: BorderStyle.SINGLE, size: 4, color: "D6E4F0", space: 6 },
    right: { style: BorderStyle.SINGLE, size: 4, color: "D6E4F0", space: 6 } };
  return [
    new Paragraph({
      spacing: { before: 220, after: 0 },
      shading: { type: ShadingType.CLEAR, fill: BG_LIGHT },
      border: { ...frame, left: { style: BorderStyle.SINGLE, size: 20, color: PRIMARY, space: 8 } },
      children: [new TextRun({ text: title, bold: true, color: PRIMARY_DARK, size: 21, font: FONT })],
    }),
    new Paragraph({
      spacing: { after: 200 },
      shading: { type: ShadingType.CLEAR, fill: BG_LIGHT },
      border: { left: { style: BorderStyle.SINGLE, size: 20, color: PRIMARY, space: 8 },
        bottom: { style: BorderStyle.SINGLE, size: 4, color: "D6E4F0", space: 6 },
        right: { style: BorderStyle.SINGLE, size: 4, color: "D6E4F0", space: 6 } },
      children: [new TextRun({ text: desc, color: "222222", size: 19, font: FONT })],
    }),
  ];
}

