const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  Table, TableRow, TableCell, WidthType, ShadingType, VerticalAlign,
  PageBreak, LevelFormat, BorderStyle, ExternalHyperlink,
} = require("docx");

const FONT = "Calibri";
const PRIMARY = "1F6FB2";
const PRIMARY_DARK = "0C447C";
const BG_LIGHT = "EAF2FB";
const TEXT_MUTED = "6B6B6B";

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 400, after: 200 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: PRIMARY, space: 6 } },
    children: [
      new TextRun({ text: "  ", shading: { type: ShadingType.CLEAR, fill: PRIMARY } }),
      new TextRun({ text: "  " + text, bold: true, color: PRIMARY_DARK, size: 30, font: FONT }),
    ],
  });
}
function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 240, after: 100 },
    children: [new TextRun({ text, bold: true, color: PRIMARY_DARK, size: 23, font: FONT })],
  });
}
function body(text, opts = {}) {
  return new Paragraph({
    spacing: { after: 140 },
    children: [new TextRun({ text, font: FONT, size: 22, color: "222222", ...opts })],
  });
}
function note(text) {
  return new Paragraph({
    spacing: { after: 200 },
    shading: { type: ShadingType.CLEAR, fill: BG_LIGHT },
    border: { left: { style: BorderStyle.SINGLE, size: 18, color: PRIMARY, space: 8 } },
    indent: { left: 60 },
    children: [new TextRun({ text, color: PRIMARY_DARK, font: FONT, size: 19 })],
  });
}
function bullet(text, opts = {}) {
  return new Paragraph({
    numbering: { reference: "bullet-list", level: opts.level || 0 },
    spacing: { after: 90 },
    children: [new TextRun({ text, font: FONT, size: 22, bold: !!opts.bold, color: "222222" })],
  });
}
function cell(text, opts = {}) {
  const fill = opts.header ? PRIMARY_DARK : opts.sub ? BG_LIGHT : undefined;
  const textColor = opts.header ? "FFFFFF" : "1A1A1A";
  return new TableCell({
    width: { size: opts.width || 2000, type: WidthType.DXA },
    verticalAlign: VerticalAlign.CENTER,
    shading: fill ? { type: ShadingType.CLEAR, fill } : undefined,
    margins: { top: 80, bottom: 80, left: 100, right: 100 },
    children: [new Paragraph({
      children: [new TextRun({ text, bold: !!opts.header || !!opts.bold, color: textColor, font: FONT, size: opts.size || 19 })],
    })],
  });
}
function link(text, url) {
  return new Paragraph({
    spacing: { after: 160 },
    children: [new ExternalHyperlink({
      link: url,
      children: [new TextRun({ text, style: "Hyperlink", font: FONT, size: 22 })],
    })],
  });
}

